CREATE procedure MM_SP_ConsultarHistorialCambiosCantidadAP	@IdAceptacionPedido INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT h.IdHistorialCorreccionCantidadAP,			PD.IdMaterialVendedor AS IdMaterial,			POD.MaterialCotizadoTextoC AS DescripcionCorta,			POD.MaterialCotizadoTextoL AS DescripcionLarga,			h.CantidadAnterior,			h.CantidadNueva,			h.Motivo,			u.Nombre,			h.ModificadoEl	FROM dbo.MM_HistorialCorreccionCantidadAP h		INNER JOIN dbo.MM_AceptacionPedidoDetalle a ON a.IdAceptacionPedido = h.IdAceptacionPedido 													AND a.IdAceptacionPedidoDetalle = h.IdAeptacionPedidoDetalle				INNER JOIN MM_PedidoDetalle AS PD ON PD.IdPedidoDetalle = a.IdPedidoDetalle		INNER JOIN dbo.MM_PeticionOfertaDetalle AS POD ON POD.IdPeticionOfertaDetalle = PD.IdPeticionOfertaDetalle		INNER JOIN dbo.S_Usuario u ON u.IdUsuario = h.ModificadoPor	WHERE h.IdAceptacionPedido = @IdAceptacionPedidoEND